from math import comb, exp, factorial

# Nhị thức: n lần thử độc lập, mỗi lần thành công với xác suất p
def binom_pmf(k, n, p):
    return comb(n, k) * p**k * (1 - p)**(n - k)

# 20 khách vào cửa hàng, mỗi người mua với xác suất 0.3
print("P(đúng 6 người mua) =", round(binom_pmf(6, 20, 0.3), 4))
print("P(>=10 người mua)  =", round(sum(binom_pmf(k, 20, 0.3) for k in range(10, 21)), 4))

# Poisson: số sự kiện trong một khoảng, tốc độ trung bình lam
def poisson_pmf(k, lam):
    return exp(-lam) * lam**k / factorial(k)

# Tổng đài trung bình 3 cuộc gọi/phút
print("P(0 cuộc gọi) =", round(poisson_pmf(0, 3), 4))
